window.BABA.NarrationEN = {"questNames": {"text": "You have passed judgment on their names. Your choice is carved in stone.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 5.75, "audio": ""}, "questVerdict": {"text": "The sentence written in blood has changed. The executioner will pay the price.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 6.42, "audio": ""}, "questBell": {"text": "The bell’s final word is now yours.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 3.58, "audio": ""}, "questMemory": {"text": "You have claimed the memories hidden in the roots.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 3.22, "audio": ""}, "questKing": {"text": "You have judged the name the king concealed. The throne’s first bond is broken.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 6.97, "audio": ""}, "questEcho": {"text": "The cavern breathes differently. Your judgment will remain here.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 4.95, "audio": ""}, "questPrisoner": {"text": "The final oath in the pit is sealed. Your decision cannot be undone.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 5.83, "audio": ""}, "questHeart": {"text": "The furnace has a new source of power. The final judgment draws near.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 6.19, "audio": ""}, "ruinsIntro": {"text": "The kingdom lies beneath the earth. Find the passage behind the throne.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 5.85, "audio": ""}, "ruinsCheckpoint": {"text": "The Last Oath is sealed. The throne awaits you.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 4.49, "audio": ""}, "ruinsBoss": {"text": "The King of the Hollows. Bring down his throne.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 4.15, "audio": ""}, "ruinsWin": {"text": "The throne has fallen. The gate beneath it is open. Beyond lies the furnace where the chains were forged.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 8.69, "audio": ""}, "forgeIntro": {"text": "These chains were forged in this furnace. Destroy their source.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 5.27, "audio": ""}, "forgeCheckpoint": {"text": "The Ember Oath is sealed. The Final Casting awaits you.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 4.85, "audio": ""}, "forgeBoss": {"text": "The Heart of the Furnace. Extinguish its final flame.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 4.82, "audio": ""}, "forgeWin": {"text": "The furnace is silent. The last chain has melted. Now, keep walking.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 7.16, "audio": ""}, "coastIntro": {"text": "The sea has swallowed this shore. Silence the bell. Carve a path for yourself.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 7.21, "audio": ""}, "coastRoots": {"text": "Hearts still beat beneath the burned trees. Every root reaches toward someone buried in the earth.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 7.33, "audio": ""}, "coastStreet": {"text": "They locked their doors from within. As the waters rose, no one helped their neighbor. Now they all wait in the same street.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 10.21, "audio": ""}, "coastPier": {"text": "Do not follow the lanterns. Those lights called the boats into the depths, never to the shore.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 7.38, "audio": ""}, "coastSquare": {"text": "Hundreds of graves lie beneath the square. The bellringer forgot their names. The roots did not.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 8.24, "audio": ""}, "coastCheckpoint": {"text": "Your oath will remain in this lantern. Go to the belfry.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 4.78, "audio": ""}, "coastBoss": {"text": "The Bellringer of the Depths. Silence his bell.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 4.01, "audio": ""}, "coastDeath": {"text": "The sea has not claimed you yet. Your oath calls you back to the shore. Rise.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 7.58, "audio": ""}, "coastDeath2": {"text": "This time, the roots could not hold you. But the darkness has learned your name. Walk again.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 7.79, "audio": ""}, "coastDeath3": {"text": "The bell still tolls for you. If you wish to leave this shore, silence it.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 5.76, "audio": ""}, "coastSeal": {"text": "The roots have loosened. Venture farther inland.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 4.1, "audio": ""}, "coastWin": {"text": "The bell is silent. The sea is receding. The path leads to the buried kingdom.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 7.45, "audio": ""}, "intro": {"text": "They thought you dead and cast you here. Rise, Bahtiyar. Break the executioner’s chain.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 8.54, "audio": ""}, "chains": {"text": "These guards were the executioner’s first victims. Even now, the chains around their necks bind them to his will.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 9.45, "audio": ""}, "ritual": {"text": "They brought the wounded here to be healed. The priests fed the ritual with their suffering.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 6.2, "audio": ""}, "crypt": {"text": "The blood spilled on the altar gives the executioner strength. This temple will not fall silent until the ritual ends.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 9.12, "audio": ""}, "rot": {"text": "These bones were torn from their graves. They became mortar between the stones of the passage. They sustain the executioner’s chain.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 11.51, "audio": ""}, "checkpoint": {"text": "The oathstone will remember you. Your path is open.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 4.58, "audio": ""}, "boss": {"text": "The executioner stands before you. Break his chain.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 4.77, "audio": ""}, "heroOath": {"text": "I will not leave them here.", "speaker": "Bahtiyar", "voice": "en-US-EricNeural", "style": "H", "duration": 1.83, "audio": ""}, "cellat": {"text": "No one passes through this gate.", "speaker": "Chain Executioner", "voice": "en-US-ChristopherNeural", "style": "E", "duration": 2.92, "audio": ""}, "seal": {"text": "Another link in the chain has broken. Move on.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 4.31, "audio": ""}, "death": {"text": "Your oath remains unbroken. The stone calls you back.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 4.85, "audio": ""}, "death2": {"text": "This grave cannot hold you. Rise.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 3.81, "audio": ""}, "death3": {"text": "You have fallen once more. But your oath is unbroken. Rise again, and break the chain.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 8.07, "audio": ""}, "win": {"text": "The executioner is silent. The chain is broken. Beyond the open gate, a bell awaits.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 8.8, "audio": ""}};
